 writeFileSync(join(contentDir,'catalog.json'),JSON.stringify(catalog));writeFileSync(join(contentDir,'don-quixote.json'),JSON.stringify({id:'don-quixote',title:'Test Don Quixote',author:'Cervantes',chapters:[{id:'chapter-1',title:'Chapter 1',tags:['authored-opening'],objectiveOccurrences:[{objectiveId:'authored-opening',count:1,locations:[{sentenceId:'sentence-1',text:'La casa'}]}],sentences:[{id:'sentence-1',text:'La casa es pequeña.',page:1,tags:['authored-opening'],objectiveSpans:[{objectiveId:'authored-opening',spans:['La casa']}]}]},{id:'long-chapter',title:'Long chapter',sentences:Array.from({length:85},(_,i)=>({id:`long-${i+1}`,text:`Oración ${i+1}.`,page:null,tags:[]}))}]}));
 const messages=[],options={dataDir:dir,contentDir,worker:false,env:{NODE_ENV:'test',APP_ORIGIN:origin,ADMIN_EMAILS:'admin@example.test'},mailSender:async message=>messages.push(message),...extra};let runtime=createApp(options);
 let server=runtime.app.listen(0,'127.0.0.1');await new Promise(r=>server.once('listening',r));
