 function client(){let cookie='',userId='';return async(path,method='GET',body,headers={})=>{const auth=['/api/auth/register','/api/auth/login','/api/auth/verify','/api/auth/forgot-password','/api/auth/reset-password'].includes(path),response=await fetch(base+path,{method,headers:{...(body!==undefined?{'content-type':'application/json'}:{}),...(method!=='GET'?{origin}:{}),...(cookie?{cookie}:{}),...(userId&&method!=='GET'&&!auth?{'x-expected-account-id':userId}:{}),...headers},body:body===undefined?undefined:Buffer.isBuffer(body)?body:JSON.stringify(body)});if(response.headers.get('set-cookie'))cookie=response.headers.get('set-cookie').split(';')[0];const result={status:response.status,body:await response.json(),headers:response.headers};if(result.body.user?.id)userId=result.body.user.id;if(['/api/auth/logout','/api/account'].includes(path)&&response.ok)userId='';return result;};}
