test('BKT numerical update and readiness threshold are deterministic',()=>{assert.ok(Math.abs(updateBkt(.2,true)-.5368421052631579)<1e-12);assert.ok(Math.abs(updateBkt(.2,false)-.14838709677419354)<1e-12);assert.equal(readiness(null).status,'unknown');const row={probability:.95,successes:3,itemCount:2,updatedAt:new Date().toISOString()};assert.equal(readiness(row).status,'skip');assert.equal(readiness({...row,itemCount:1}).status,'teach');assert.equal(readiness({...row,updatedAt:'2020-01-01T00:00:00Z'}).status,'refresh');assert.equal(MODEL.version,'bkt-v1');});
