 await api('/api/auth/logout','POST',{});assert.equal((await api('/api/placement')).status,401);await api('/api/auth/login','POST',{email:'reader@example.test',password:'correct horse battery staple'});assert.equal((await api('/api/placement')).body.index,1);for(let i=2;i<=3;i++)await api('/api/placement/answer','POST',{questionId:`q${i}`,choiceIndex:0,attemptId:`next-attempt-${i}`});assert.equal((await api('/api/bootstrap')).body.onboarding.status,'complete');
 const lesson=(await api('/api/lessons/lesson-1')).body.lesson;assert.equal(lesson.questions[0].answerIndex,undefined);assert.equal(lesson.questions[0].explanation,undefined);await api('/api/lessons/lesson-1/assist','POST',{questionId:'q4',kind:'reveal'});result=await api('/api/lessons/lesson-1/answer','POST',{questionId:'q4',choiceIndex:0,attemptId:'assisted-test-1',assisted:false});assert.equal(result.body.scored,false);assert.equal(f.runtime.db.prepare('SELECT count(*) AS n FROM bkt_history').get().n,3);
