test('durable upload jobs automatically structure source-bound text and enforce ownership, idempotency, quota and cancellation',async t=>{const f=await fixture(t,{pdfAdapter:{extractPdf:async({onProgress})=>{onProgress(.2,'Extracting');onProgress(1,'Extracted');return {pages:[{page:1,text:'HEADER\nLa casa es pequeña.'},{page:2,text:''}],warnings:['Page 2 is blank.']};}},aiAdapter:{runTask:async({kind,input,onProgress})=>{assert.equal(kind,'document');onProgress(.1,'Structuring');onProgress(1,'Structured');return {edits:[{page:1,source:'HEADER\n',replacement:''}],sections:[{title:'Document',page:1,anchor:'La casa es pequeña.'}]};}}}),api=await f.account();await f.place(api);const headers={'content-type':'application/pdf','x-filename':'sample.pdf','idempotency-key':'upload-request-1'};const bytes=Buffer.from('%PDF-1.7 test fixture');const upload=await api('/api/books/upload','POST',bytes,headers);assert.equal(upload.status,202,JSON.stringify(upload.body));const again=await api('/api/books/upload','POST',bytes,headers);assert.equal(again.body.job.id,upload.body.job.id);assert.equal((await api('/api/bootstrap')).body.quotas.uploads.used,1);await f.runtime.processQueue();const job=(await api(`/api/jobs/${upload.body.job.id}`)).body.job;assert.equal(job.status,'completed',JSON.stringify(job));assert.equal(job.result.status,'ready');const ready=(await api(`/api/books/${upload.body.bookId}`)).body.book;assert.equal(ready.status,'ready');assert.equal(ready.rawPages[0].text,'HEADER\nLa casa es pequeña.');assert.equal(ready.pages[0].text,'La casa es pequeña.');assert.equal(ready.chapters[0].title,'Document');assert.equal((await api(`/api/books/${upload.body.bookId}/confirm`,'POST',{})).status,404);
 const other=await f.account('other@example.test');assert.equal((await other(`/api/books/${upload.body.bookId}`)).status,404);assert.equal((await other(`/api/jobs/${upload.body.job.id}`)).status,404);assert.equal((await other(`/api/jobs/${upload.body.job.id}/cancel`,'POST',{})).status,404);
 for(let i=2;i<=3;i++){const up=await api('/api/books/upload','POST',bytes,{...headers,'idempotency-key':`upload-request-${i}`});assert.equal(up.status,202);assert.equal((await api(`/api/jobs/${up.body.job.id}/cancel`,'POST',{})).body.job.status,'cancelled');}assert.equal((await api('/api/books/upload','POST',bytes,{...headers,'idempotency-key':'upload-request-4'})).status,429);assert.equal((await api('/api/books/upload','POST',Buffer.from('invalid pdf'),headers)).status,422);});
test('owned upload deletion aborts active work, removes private state and is effect-idempotent',async t=>{let startedResolve,release;const started=new Promise(resolve=>startedResolve=resolve),hold=new Promise(resolve=>release=resolve);const f=await fixture(t,{pdfAdapter:{extractPdf:async()=>{startedResolve();await hold;return {pages:[{page:1,text:'La casa es pequeña.'}],warnings:[]};}},aiAdapter:{runTask:async({input})=>documentPlan(input.pages)}}),owner=await f.account(),other=await f.account('delete-other@example.test'),upload=await owner('/api/books/upload','POST',Buffer.from('%PDF-1.7 delete fixture'),{'content-type':'application/pdf','x-filename':'delete.pdf','idempotency-key':'delete-upload'}),path=join(f.runtime.db.prepare('SELECT path FROM books WHERE id=?').get(upload.body.bookId).path);const worker=f.runtime.processQueue();await started;assert.equal((await other(`/api/books/${upload.body.bookId}`,'DELETE',{})).status,404);assert.equal((await owner('/api/books/don-quixote','DELETE',{})).body.code,'PUBLIC_BOOK');const unconfirmed=await owner(`/api/books/${upload.body.bookId}`,'DELETE',{confirmation:'remove'});assert.equal(unconfirmed.status,400);assert.equal(unconfirmed.body.code,'CONFIRMATION_REQUIRED');assert.equal(f.runtime.db.prepare('SELECT count(*) AS n FROM books WHERE id=?').get(upload.body.bookId).n,1);assert.equal(existsSync(path),true);const uploadDir=join(path,'..');let denied;chmodSync(uploadDir,0o500);try{denied=await owner(`/api/books/${upload.body.bookId}`,'DELETE',{confirmation:'REMOVE'});}finally{chmodSync(uploadDir,0o700);}assert.equal(denied.status,500);assert.equal(f.runtime.db.prepare('SELECT count(*) AS n FROM books WHERE id=?').get(upload.body.bookId).n,1);assert.equal(existsSync(path),true);assert.equal((await owner(`/api/books/${upload.body.bookId}`,'DELETE',{confirmation:'REMOVE'})).status,200);assert.equal(existsSync(path),false);assert.equal((await owner(`/api/books/${upload.body.bookId}`,'DELETE',{confirmation:'REMOVE'})).status,404);release();await worker;assert.equal(f.runtime.db.prepare('SELECT count(*) AS n FROM books WHERE id=?').get(upload.body.bookId).n,0);assert.equal(f.runtime.db.prepare('SELECT count(*) AS n FROM jobs WHERE bookId=?').get(upload.body.bookId).n,0);
 const user=(await owner('/api/bootstrap')).body.user;await f.place(owner);const id='delete-with-history',time=new Date().toISOString(),file=join(path,'..',`${id}.pdf`),shared={...question(50),id:'shared-delete-question'},unique={...question(51),id:'unique-delete-question'},lesson={id:'delete-lesson',bookId:id,objectiveIds:['test-objective'],questions:[shared,unique]},retained={id:'retained-lesson',bookId:'don-quixote',objectiveIds:['test-objective'],questions:[shared]};writeFileSync(file,'private');f.runtime.db.prepare('INSERT INTO books VALUES(?,?,?,?,?,?)').run(id,user.id,JSON.stringify({id,title:'Delete history',chapters:[]}),'ready',file,time);f.runtime.db.prepare('INSERT INTO lessons VALUES(?,?,?,?,?)').run(lesson.id,user.id,id,JSON.stringify(lesson),time);f.runtime.db.prepare('INSERT INTO lessons VALUES(?,?,?,?,?)').run(retained.id,user.id,'don-quixote',JSON.stringify(retained),time);f.runtime.db.prepare('INSERT INTO curricula VALUES(?,?,?,?,?,?)').run('delete-curriculum',user.id,id,1,JSON.stringify({lessons:[{id:lesson.id}]}),time);assert.equal((await owner(`/api/lessons/${retained.id}/assist`,'POST',{questionId:shared.id,kind:'hint'})).status,200);f.runtime.db.prepare('INSERT INTO assistance VALUES(?,?,?,?,?)').run(user.id,unique.id,'1','hint',time);f.runtime.db.prepare('INSERT INTO vocabulary VALUES(?,?,?,?,?,?,?,?,?)').run('delete-card',user.id,id,null,'front','back','{}',time,time);f.runtime.db.prepare('INSERT INTO reviews VALUES(?,?,?,?,?)').run('delete-review',user.id,'delete-card','{}',time);f.runtime.db.prepare('INSERT INTO review_queue VALUES(?,?,?,?,?,?,?,?)').run('delete-feedback',user.id,id,'feedback','pending','{}',null,time);f.runtime.db.prepare('INSERT INTO events VALUES(?,?,?,?,?,?)').run('delete-event',user.id,null,'review_resolution',JSON.stringify({reviewId:'delete-feedback'}),time);f.runtime.db.prepare('INSERT INTO events VALUES(?,?,?,?,?,?)').run('delete-document-event',user.id,null,'transition',JSON.stringify({node:'book',event:'confirm',bookId:id,title:'Delete history'}),time);const answer=await owner(`/api/lessons/${lesson.id}/answer`,'POST',{questionId:shared.id,choiceIndex:0,attemptId:'delete-attempt'});assert.equal(answer.status,200);assert.equal(f.runtime.db.prepare("SELECT count(*) AS n FROM events WHERE json_extract(data,'$.attemptId')='delete-attempt'").get().n,1);assert.equal((await owner(`/api/books/${id}`,'DELETE',{confirmation:'REMOVE'})).status,200);for(const [table,where] of [['books','id'],['lessons','bookId'],['curricula','bookId'],['vocabulary','bookId'],['review_queue','bookId']])assert.equal(f.runtime.db.prepare(`SELECT count(*) AS n FROM ${table} WHERE ${where}=?`).get(id).n,0);assert.equal(f.runtime.db.prepare("SELECT count(*) AS n FROM assistance WHERE questionId='unique-delete-question'").get().n,0);assert.equal(f.runtime.db.prepare("SELECT count(*) AS n FROM assistance WHERE questionId='shared-delete-question'").get().n,1);assert.equal(f.runtime.db.prepare("SELECT count(*) AS n FROM attempts WHERE id='delete-attempt'").get().n,0);assert.equal(f.runtime.db.prepare("SELECT count(*) AS n FROM events WHERE json_extract(data,'$.attemptId')='delete-attempt'").get().n,0);assert.equal(f.runtime.db.prepare("SELECT count(*) AS n FROM reviews WHERE itemId='delete-card'").get().n,0);assert.equal(f.runtime.db.prepare("SELECT count(*) AS n FROM events WHERE id IN ('delete-event','delete-document-event')").get().n,0);const tombstones=f.runtime.db.prepare("SELECT kind,data FROM events WHERE userId=? AND json_extract(data,'$.bookId')=?").all(user.id,id);assert.equal(tombstones.length,1);assert.equal(tombstones[0].kind,'transition');assert.deepEqual(JSON.parse(tombstones[0].data),{node:'book',event:'delete',from:'ready',to:'removed',bookId:id});assert.equal(tombstones[0].data.includes('Delete history'),false);assert.equal((await owner(`/api/lessons/${retained.id}`)).body.progress.assistance[0].kind,'hint');});
