 assert.equal(rejectedJob.status,'completed');assert.equal(rejectedJob.result.status,undefined);assert.deepEqual(rejectedJob.result,{reviewId:first.id,decision:'reject',message:'This proposal was not approved. Your current lessons and reader are still available.'});
 assert.equal((await api('/api/books/don-quixote/curriculum')).body.curriculum.lessons[0].id,'lesson-1');
 assert.equal((await admin(`/api/admin/reviews/${first.id}/resolve`,'POST',{decision:'reject',reason:'Repeated click.'})).status,409);
 const held=(await api('/api/books/don-quixote/curriculum','POST',{passageId:'chapter-1'})).body.job;await f.runtime.processQueue();
